using System;using System.IO;using System.Net;using System.Net.Sockets;using System.Reflection;using System.Text;using System.Threading.Tasks;using CiyuanWindows;
class RecoveryTests{static int Main(){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{int port=((IPEndPoint)listener.LocalEndpoint).Port;var serving=Task.Run(()=>{for(int i=0;i<2;i++)using(var socket=listener.AcceptTcpClient())using(var stream=socket.GetStream()){var request=new StringBuilder();int b;while((b=stream.ReadByte())>=0){request.Append((char)b);if(request.ToString().EndsWith("\r\n\r\n"))break;}string body=i==0?"temporary failure":"{\"hosts\":[\"https://recovered.example.invalid\"]}";byte[] response=Encoding.UTF8.GetBytes("HTTP/1.1 "+(i==0?503:200)+" Test\r\nContent-Type: application/json\r\nContent-Length: "+Encoding.UTF8.GetByteCount(body)+"\r\nConnection: close\r\n\r\n"+body);stream.Write(response,0,response.Length);}});
 using(var content=new ContentClient()){typeof(ContentClient).GetField("api",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(content,new ApiClient("http://127.0.0.1:"+port));var first=content.InvokeAsync("sources",J.Map()).GetAwaiter().GetResult();if(!Object.Equals(J.Get(first,"isFallback"),true))throw new Exception("Initial offline state absent");var second=content.InvokeAsync("sources",J.Map()).GetAwaiter().GetResult();if(Object.Equals(J.Get(second,"isFallback"),true)||J.Arr(J.Get(second,"hosts")).Length!=1)throw new Exception("Retry remained on cached fallback after server recovered");}
 if(!serving.Wait(1000))throw new Exception("Recovered service was not queried");Console.WriteLine("PASS offline service recovers on next explicit content action");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e.GetBaseException().Message);return 1;}finally{listener.Stop();}}}
